  const [users, setUsers] = useState(() => { const withK = withUserKeys; try { const s = localStorage.getItem('loggia_users'); if (s) { const a = JSON.parse(s); if (Array.isArray(a) && a.length) return withK(a); } } catch {} return withK(FIRST_USER()); });
